"""Synthetic patch tracking through actual video decode and UI."""
exec(open(__file__.replace('patch-tracking.py','smoke.py')).read().split('with sync_playwright()')[0])
import subprocess
from PIL import Image,ImageDraw
folder=Path('/tmp/alya-track-frames');folder.mkdir(exist_ok=True)
for i in range(60):
 im=Image.new('RGB',(320,180),(35,45,60));d=ImageDraw.Draw(im);x=70+round(i*1.5);y=90;d.rectangle((x-14,y-14,x+14,y+14),fill='white');d.line((x-13,y-13,x+13,y+13),fill='black',width=4);d.rectangle((x-10,y+2,x-2,y+10),fill='red');im.save(folder/f'{i:03}.png')
subprocess.run(['ffmpeg','-y','-framerate','30','-i',str(folder/'%03d.png'),'-c:v','libx264','-pix_fmt','yuv420p','/tmp/alya-track.mp4','-loglevel','error'],check=True)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/google-chrome',headless=True,args=['--no-sandbox']);page=b.new_page(viewport={'width':360,'height':800});page.goto(base);page.click('#btn-new-project');page.set_input_files('#file-video','/tmp/alya-track.mp4');page.wait_for_function('window.__alya.state.clips.length===1');page.click('[data-panel=overlays]');page.click('#ov-add-emoji');page.evaluate('Object.assign(window.__alya.state.overlays[0],{x:70/320*100,y:50,start:0,end:1.9});document.querySelector("#ov-start").value=0;document.querySelector("#ov-end").value=1.9');page.locator('#panel-overlays details summary').filter(has_text='Experimental patch').click();page.click('#ov-track-patch');page.wait_for_function('document.querySelector("#ov-track-status").textContent.includes("points applied")',timeout=30000);points=page.evaluate('window.__alya.state.overlays[0].keyframes');assert len(points)==8 and points[-1]['x']>45,points;assert all(abs(k['y']-50)<3 for k in points),points;page.locator('#ov-track-status').scroll_into_view_if_needed();page.wait_for_timeout(300);page.screenshot(path='/downloads/patch-tracking.png');page.click('#ov-done');page.click('#panel-overlays .panel-close');page.click('#btn-undo');assert page.evaluate('!window.__alya.state.overlays[0].keyframes')
 page.evaluate('()=>{window.__alya.state.clips[0].flipX=true;Object.assign(window.__alya.state.overlays[0],{x:(320-70)/320*100,y:50});window.__alya.refreshAll();}');page.click('[data-panel=overlays]');page.locator('#ov-list button').first.click();page.click('#ov-track-patch');page.wait_for_function('document.querySelector("#ov-track-status").textContent.includes("points applied")',timeout=30000);points=page.evaluate('window.__alya.state.overlays[0].keyframes');assert points[0]['x']>75 and points[-1]['x']<55,points;page.locator('#ov-track-status').scroll_into_view_if_needed();page.wait_for_timeout(300);page.screenshot(path='/downloads/flipped-patch-tracking.png');page.click('#ov-done');page.click('#panel-overlays .panel-close');page.click('#btn-undo');assert page.evaluate('!window.__alya.state.overlays[0].keyframes')
 page.click('[data-panel=overlays]');page.locator('#ov-list button').first.click();page.evaluate('()=>{AlyaTracking.track=()=>new Promise(r=>window.finishTrack=r);return true;}');page.click('#ov-track-patch');page.wait_for_function('!!window.finishTrack');page.evaluate('window.__alya.state.overlays[0].x=30;window.finishTrack([{at:0,x:20,y:50},{at:1,x:50,y:50}])');page.wait_for_function('!document.querySelector("#ov-track-patch").disabled');assert 'discarded' in page.locator('#ov-track-status').inner_text();assert page.evaluate('!window.__alya.state.overlays[0].keyframes')
 result=page.evaluate("()=>{const data=new Uint8ClampedArray(160*90*4).fill(100),p=AlyaTracking.patch(data,160,90,80,45);return AlyaTracking.variance(p);}");assert result==0
 print('PASS: real video8-frame textured patch movement, flipped source, vertical stability and Undo; plain-patch variance zero. Synthetic/simple motion only, not real object tracking proof.');b.close()
